head.b:skin:
:root {
  --navy: #0B1530;
  --navy-soft: #111D3A;
  --gold: #D4AF37;
  --paper: #F5F7FB;
  --white: #FFFFFF;
  --ink: #283247;
  --muted: #5C6678;
  --line: #E1E7F0;
  --radius: 16px;
  --shadow: 0 14px 36px rgba(11, 21, 48, .08);
}
* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 16px/1.7 Arial, Helvetica, sans-serif;
}
a { color: #173D70; text-decoration: none; }
a:hover { color: #8A6714; text-decoration: underline; }
a:focus-visible, button:focus-visible, input:focus-visible {
  outline: 3px solid var(--gold);
  outline-offset: 3px;
}
img { max-width: 100%; height: auto; }
.wrap { width: min(1160px, calc(100% - 36px)); margin-inline: auto; }
.skip-link {
  position: absolute; z-index: 20; left: 12px; top: -80px;
  padding: 10px 14px; background: var(--white); color: var(--navy);
  border-radius: 8px; box-shadow: var(--shadow);
}
.skip-link:focus { top: 12px; }
.topbar {
  padding: 7px 16px; background: #081126; color: #E9EDF4;
  text-align: center; font-size: 13px; letter-spacing: .02em;
}
.site-header {
  color: var(--white);
  background: linear-gradient(120deg, var(--navy), var(--navy-soft));
  border-bottom: 4px solid var(--gold);
}
.masthead {
  display: grid; grid-template-columns: minmax(230px, 1fr) minmax(220px, 340px);
  align-items: center; gap: 22px; padding-block: 20px;
}
.header-section, .header-section .widget { min-width: 0; margin: 0; }
.header-section .widget-content { color: #E9EDF4; }
.header-section h1, .header-section h2, .header-section .title {
  margin: 0; color: var(--white); font-size: clamp(24px, 3vw, 34px);
  line-height: 1.18; font-weight: 800;
}
.header-section h1 a, .header-section h2 a, .header-section .title a { color: inherit; }
.header-section img { max-height: 72px; width: auto; object-fit: contain; }
.tagline { margin: 7px 0 0; color: #DFE5EF; font-size: 14px; }
.search-form { display: flex; gap: 8px; width: 100%; }
.search-form input {
  min-width: 0; flex: 1; border: 1px solid rgba(255,255,255,.35);
  border-radius: 9px; padding: 10px 12px; color: var(--ink); background: var(--white);
  font: inherit;
}
.search-form button {
  border: 0; border-radius: 9px; padding: 10px 13px;
  color: var(--navy); background: var(--gold); font: inherit; font-weight: 700;
  cursor: pointer;
}
.visually-hidden {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}
.primary-nav { background: rgba(4, 12, 29, .35); }
.primary-nav__row { display: flex; align-items: center; min-height: 56px; gap: 14px; }
.menu-toggle {
  display: none; align-items: center; gap: 8px; border: 1px solid rgba(255,255,255,.35);
  border-radius: 8px; background: transparent; color: var(--white);
  padding: 8px 12px; font: inherit; font-weight: 700; cursor: pointer;
}
.primary-nav__links { display: flex; align-items: center; gap: 8px; width: 100%; }
.primary-nav .navbar, .primary-nav .PageList { margin: 0; min-width: 0; }
.primary-nav .PageList .title, .primary-nav .PageList h2 { display: none; }
.primary-nav .PageList .widget-content, .primary-nav .PageList ul {
  display: flex; align-items: center; flex-wrap: wrap; gap: 6px;
  margin: 0; padding: 0; list-style: none;
}
.primary-nav .PageList li { margin: 0; padding: 0; }
.primary-nav .PageList a, .nav-link {
  display: inline-block; border-radius: 8px; padding: 7px 10px;
  color: var(--white); font-size: 14px; font-weight: 700;
}
.primary-nav .PageList a:hover, .nav-link:hover {
  background: rgba(255,255,255,.12); color: var(--white); text-decoration: none;
}
.nav-whatsapp {
  margin-left: auto; padding-inline: 13px !important;
  background: var(--gold); color: var(--navy) !important;
}
.nav-whatsapp:hover { background: #E5C75D !important; color: var(--navy) !important; }
.hero {
  display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(280px, .9fr);
  align-items: center; gap: clamp(20px, 4vw, 48px); margin-block: 30px;
  padding: clamp(22px, 5vw, 50px); overflow: hidden;
  border: 1px solid var(--line); border-radius: 22px;
  background: var(--white); box-shadow: var(--shadow);
}
.eyebrow {
  margin: 0 0 8px; color: #8A6714; text-transform: uppercase;
  font-size: 12px; font-weight: 800; letter-spacing: .13em;
}
.hero h2 {
  max-width: 700px; margin: 0; color: var(--navy);
  font-size: clamp(32px, 5vw, 52px); line-height: 1.08; letter-spacing: -.025em;
}
.hero-lead { margin: 16px 0 0; color: #37445A; font-size: clamp(17px, 2vw, 20px); }
.hero-note { max-width: 610px; margin: 12px 0 0; color: var(--muted); font-size: 14px; }
.hero-actions { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 23px; }
.button {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  border: 1px solid var(--navy); border-radius: 9px; padding: 10px 16px;
  background: var(--navy); color: var(--white); font-weight: 700;
  transition: transform .15s ease, background .15s ease;
}
.button:hover { transform: translateY(-1px); color: var(--white); text-decoration: none; }
.button--gold { border-color: var(--gold); background: var(--gold); color: var(--navy); }
.button--gold:hover { background: #E5C75D; color: var(--navy); }
.hero-art {
  min-height: 300px; border-radius: 17px;
  background-color: #182B50;
  background-image: linear-gradient(100deg, rgba(11,21,48,.04), rgba(11,21,48,.12)),
    url('https://raw.githubusercontent.com/Meelad5815/BlogSpot-/main/assets/mrk-digital-hero.jpg');
  background-size: cover; background-position: center;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.15);
}
.section { margin-block: 40px; }
.section-heading {
  display: flex; align-items: end; justify-content: space-between;
  gap: 14px; margin-bottom: 17px;
}
.section-heading h2, .section-title {
  margin: 0; color: var(--navy); font-size: clamp(23px, 3vw, 30px); line-height: 1.2;
}
.section-heading p { max-width: 640px; margin: 6px 0 0; color: var(--muted); }
.service-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 15px; }
.service-card {
  min-width: 0; overflow: hidden; border: 1px solid var(--line);
  border-radius: 14px; background: var(--white); box-shadow: 0 7px 22px rgba(11,21,48,.045);
}
.service-art {
  min-height: 142px; background-color: #DCE5F2;
  background-size: cover; background-position: center;
}
.art-web { background-image: linear-gradient(180deg, rgba(11,21,48,.02), rgba(11,21,48,.24)), url('https://raw.githubusercontent.com/Meelad5815/BlogSpot-/main/assets/website-development.jpg'); }
.art-wordpress { background-image: linear-gradient(180deg, rgba(11,21,48,.02), rgba(11,21,48,.24)), url('https://raw.githubusercontent.com/Meelad5815/BlogSpot-/main/assets/website-development.jpg'); }
.art-marketing { background-image: linear-gradient(180deg, rgba(11,21,48,.02), rgba(11,21,48,.24)), url('https://raw.githubusercontent.com/Meelad5815/BlogSpot-/main/assets/seo-marketing.jpg'); }
.art-online { background-image: linear-gradient(180deg, rgba(11,21,48,.02), rgba(11,21,48,.24)), url('https://raw.githubusercontent.com/Meelad5815/BlogSpot-/main/assets/online-services.jpg'); }
.art-freelance { background-image: linear-gradient(180deg, rgba(11,21,48,.02), rgba(11,21,48,.24)), url('https://raw.githubusercontent.com/Meelad5815/BlogSpot-/main/assets/freelancing.jpg'); }
.art-plc { background-image: linear-gradient(180deg, rgba(11,21,48,.02), rgba(11,21,48,.24)), url('https://raw.githubusercontent.com/Meelad5815/BlogSpot-/main/assets/plc-automation.jpg'); }
.art-arduino { background-image: linear-gradient(180deg, rgba(11,21,48,.02), rgba(11,21,48,.24)), url('https://raw.githubusercontent.com/Meelad5815/BlogSpot-/main/assets/arduino-electronics.jpg'); }
.art-design { background-image: linear-gradient(180deg, rgba(11,21,48,.02), rgba(11,21,48,.24)), url('https://raw.githubusercontent.com/Meelad5815/BlogSpot-/main/assets/graphic-design.jpg'); }
.service-card__body { padding: 16px; }
.service-card h3 { margin: 0 0 6px; color: var(--navy); font-size: 17px; line-height: 1.3; }
.service-card p { margin: 0; color: var(--muted); font-size: 14px; }
.feature-panel {
  display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 22px;
  padding: clamp(22px, 4vw, 34px); border-radius: var(--radius);
  border: 1px solid #D9E1EC; background: linear-gradient(120deg, #FFFFFF, #EEF2F8);
}
.feature-panel h2 { margin: 0 0 8px; color: var(--navy); font-size: 25px; }
.feature-panel p { margin: 0; color: var(--muted); }
.feature-label { display: inline-block; margin-bottom: 7px; color: #8A6714; font-size: 12px; font-weight: 800; letter-spacing: .1em; text-transform: uppercase; }
.about-panel {
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(260px, .7fr);
  gap: 24px; align-items: center; padding: clamp(22px, 4vw, 36px);
  border-radius: var(--radius); background: var(--navy); color: #E8EDF5;
}
.about-panel h2 { margin: 0 0 9px; color: var(--white); font-size: 26px; }
.about-panel p { margin: 0; color: #D6DFEB; }
.about-panel__note {
  padding: 18px; border: 1px solid rgba(255,255,255,.2);
  border-radius: 12px; background: rgba(255,255,255,.06); font-size: 14px;
}
.content-layout {
  display: grid; grid-template-columns: minmax(0, 2fr) minmax(230px, .85fr);
  gap: 24px; align-items: start; margin-block: 32px 42px;
}
.main-column, .sidebar-column { min-width: 0; }
.latest-heading { margin: 0 0 15px; color: var(--navy); font-size: 27px; }
#main .widget, #main .blog-posts, #main .post-outer, #sidebar .widget {
  overflow-wrap: anywhere; border: 1px solid var(--line);
  border-radius: 13px; background: var(--white); box-shadow: 0 7px 22px rgba(11,21,48,.04);
}
#main .widget { margin-bottom: 17px; padding: clamp(16px, 3vw, 24px); }
#main .blog-posts { border: 0; background: transparent; box-shadow: none; padding: 0; }
#main .post-outer { margin-bottom: 16px; padding: clamp(16px, 3vw, 24px); }
.post-title, .post-title a, .post h3.post-title { color: var(--navy); font-size: clamp(22px, 3vw, 27px); line-height: 1.3; }
.post-title a:hover { color: #8A6714; }
.post-body { color: #303B4F; font-size: 16px; line-height: 1.8; }
.post-body h2, .post-body h3 { color: var(--navy); line-height: 1.3; }
.post-body img { max-width: 100%; height: auto; border-radius: 10px; }
.post-body table { display: block; max-width: 100%; overflow-x: auto; border-collapse: collapse; }
.post-body blockquote { margin-inline: 0; padding: 12px 18px; border-left: 4px solid var(--gold); background: #F7F4E9; }
.date-header, .post-footer, .post-timestamp, .post-author, .post-labels { color: var(--muted); font-size: 13px; }
.sidebar-column .widget { margin-bottom: 16px; padding: 18px; }
.sidebar-column .widget h2 { margin: 0 0 10px; color: var(--navy); font-size: 18px; }
.sidebar-column ul { padding-left: 20px; }
.sidebar-column li { margin-block: 5px; }
.blog-pager { display: flex; justify-content: space-between; gap: 12px; margin-block: 20px; }
.blog-pager a { display: inline-block; padding: 8px 12px; border: 1px solid var(--line); border-radius: 8px; background: var(--white); }
.breadcrumbs { margin: 18px auto 0; color: var(--muted); font-size: 13px; }
.breadcrumbs a { color: #173D70; }
.contact-strip {
  display: flex; align-items: center; justify-content: space-between;
  gap: 18px; margin-block: 30px; padding: 20px 22px;
  border: 1px solid #E9D99F; border-radius: 13px; background: #FBF8ED;
}
.contact-strip h2 { margin: 0; color: var(--navy); font-size: 21px; }
.contact-strip p { margin: 4px 0 0; color: var(--muted); font-size: 14px; }
.site-footer { margin-top: 38px; padding: 30px 0 18px; background: #081126; color: #E4EAF3; }
.footer-grid { display: grid; grid-template-columns: 1.2fr 1fr 1fr; gap: 26px; }
.site-footer h2, .site-footer h3 { margin: 0 0 10px; color: var(--white); font-size: 17px; }
.site-footer p { margin: 0; color: #C4CDDA; font-size: 14px; }
.footer-links { display: flex; flex-wrap: wrap; gap: 9px 16px; margin: 0; padding: 0; list-style: none; }
.footer-links a, .site-footer a { color: #F3D98A; }
.site-footer .widget { margin: 0; }
.copyright { margin-top: 24px; padding-top: 14px; border-top: 1px solid rgba(255,255,255,.16); color: #AEB9C9; font-size: 12px; }
.ad-slot { min-height: 0; }
@media (max-width: 900px) {
  .service-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .content-layout { grid-template-columns: minmax(0, 1.6fr) minmax(210px, .8fr); gap: 17px; }
}
@media (max-width: 720px) {
  .wrap { width: min(100% - 24px, 1160px); }
  .masthead { grid-template-columns: 1fr; gap: 12px; padding-block: 16px; }
  .search-form { max-width: 440px; }
  .primary-nav__row { display: block; padding-block: 9px; }
  .menu-toggle { display: inline-flex; }
  .primary-nav__links { flex-direction: column; align-items: stretch; gap: 8px; padding-top: 8px; }
  html.js .primary-nav__links { display: none; }
  html.js .primary-nav__links.is-open { display: flex; }
  .primary-nav .PageList .widget-content, .primary-nav .PageList ul { align-items: stretch; flex-direction: column; gap: 2px; }
  .primary-nav .PageList li, .primary-nav .PageList a, .nav-link { display: block; width: 100%; }
  .nav-whatsapp { margin-left: 0; text-align: center; }
  .hero { grid-template-columns: 1fr; margin-block: 18px; }
  .hero-art { min-height: 220px; order: -1; }
  .content-layout { grid-template-columns: 1fr; }
  .feature-panel { grid-template-columns: 1fr; }
  .about-panel { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .contact-strip { align-items: flex-start; flex-direction: column; }
}
@media (max-width: 460px) {
  .service-grid { grid-template-columns: 1fr; }
  .service-art { min-height: 180px; }
  .footer-grid { grid-template-columns: 1fr; }
  .section { margin-block: 30px; }
  .hero { padding: 17px; border-radius: 15px; }
  .hero-art { min-height: 180px; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
}

body.script:
(function () {
  var menu = document.getElementById('primary-menu');
  var toggle = document.querySelector('.menu-toggle');
  if (!menu || !toggle) return;
  document.documentElement.classList.add('js');
  function closeMenu() {
    menu.classList.remove('is-open');
    toggle.setAttribute('aria-expanded', 'false');
  }
  toggle.addEventListener('click', function () {
    var open = toggle.getAttribute('aria-expanded') === 'true';
    toggle.setAttribute('aria-expanded', String(!open));
    menu.classList.toggle('is-open', !open);
  });
  menu.addEventListener('click', function (event) {
    if (event.target.closest('a')) closeMenu();
  });
  document.addEventListener('keydown', function (event) {
    if (event.key === 'Escape') {
      closeMenu();
      toggle.focus();
    }
  });
}());
